const express = require('express');
const session = require('express-session');
const { Scalekit } = require('@scalekit-sdk/node');

const app = express();
const PORT = 3001;

// Configure express-session
app.use(session({
  secret: 'your-secret-key-change-in-production',
  resave: false,
  saveUninitialized: false,
  cookie: { secure: false } // Set to true in production with HTTPS
}));

// Initialize Scalekit client
const scalekit = new Scalekit({
  environmentId: process.env.SCALEKIT_ENVIRONMENT_ID || 'your-environment-id',
  clientId: process.env.SCALEKIT_CLIENT_ID || 'your-client-id',
  clientSecret: process.env.SCALEKIT_CLIENT_SECRET || 'your-client-secret'
});

// Helper function to generate random state string
function generateState() {
  return Math.random().toString(36).substring(2, 15) + 
         Math.random().toString(36).substring(2, 15) + 
         Math.random().toString(36).substring(2, 15);
}

// GET /login endpoint
app.get('/login', (req, res) => {
  // Get organization_id from query parameter
  const organizationId = req.query.organization_id;

  if (!organizationId) {
    return res.status(400).json({ 
      error: 'organization_id query parameter is required' 
    });
  }

  // Generate random state string for CSRF protection
  const state = generateState();

  // Store state in session
  req.session.oauthState = state;

  // Generate authorization URL using Scalekit SDK
  const authUrl = scalekit.getAuthorizationUrl({
    redirect_uri: 'http://localhost:3001/callback',
    state: state,
    organization_id: organizationId
  });

  // Redirect user to the generated authorization URL
  res.redirect(authUrl);
});

// Start the server
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

